import{_ as a,o as e,c as d,ag as r}from"./chunks/framework.CtWPcAmt.js";const g=JSON.parse('{"title":"第 11 章：管理上下文","description":"Agent 需要知道什么、文件/链接/截图/规则/历史的作用、上下文不足/过载/污染、长任务如何分阶段保存状态；产出项目上下文清单。","frontmatter":{"title":"第 11 章：管理上下文","description":"Agent 需要知道什么、文件/链接/截图/规则/历史的作用、上下文不足/过载/污染、长任务如何分阶段保存状态；产出项目上下文清单。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/11-context-management.md","filePath":"guide/11-context-management.md","lastUpdated":null}'),o={name:"guide/11-context-management.md"};function l(n,t,i,h,s,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="第-11-章-管理上下文" tabindex="-1">第 11 章：管理上下文 <a class="header-anchor" href="#第-11-章-管理上下文" aria-label="Permalink to &quot;第 11 章：管理上下文&quot;">​</a></h1><h2 id="本章解决什么问题" tabindex="-1">本章解决什么问题 <a class="header-anchor" href="#本章解决什么问题" aria-label="Permalink to &quot;本章解决什么问题&quot;">​</a></h2><p>你开始稳定使用 Agent 了，但发现它「时灵时不灵」：有时像没读过你给的材料，有时答非所问，有时把旧信息当新信息。<strong>大多数「AI 变笨了」的真相是上下文管理出了问题。</strong> 本章讲清 Agent 的「眼前」是怎么回事，并给你一份<strong>项目上下文清单</strong>，让长任务不丢、不混、不糊。</p><h2 id="从一个真实场景开始" tabindex="-1">从一个真实场景开始 <a class="header-anchor" href="#从一个真实场景开始" aria-label="Permalink to &quot;从一个真实场景开始&quot;">​</a></h2><p>第 5 章实测里，所有产品都只拿到一份裁剪过的材料包。有趣的现象发生了：</p><ul><li>多款产品的产物里出现「共同任务尚未执行」「所有产品均无记录」这类<strong>过时结论</strong>——因为材料包里没包含「测试已经完成」的信息，Agent 把「材料里没有」当成了「事实就是如此」；</li><li>一款产品的信息缺口文件里，把「材料裁剪导致缺失」当成了「项目真的缺这些内容」（TraeWork 页）。</li></ul><p><strong>这不是模型笨，是上下文不完整</strong>：Agent 只能基于你给它的上下文推理，上下文里没有的信息，它要么猜、要么误判、要么编。</p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><ol><li><strong>上下文 = Agent 本次任务的「全部视野」</strong>：你的话、它读的文件、规则、历史。没放进视野的，对它等于不存在；</li><li><strong>三类上下文问题</strong>：不足（信息太少→猜）、过载（信息太多→糊）、污染（错误信息→带偏）；</li><li><strong>材料、规则、历史要分开给</strong>：材料是「用什么做」，规则是「怎么做」，历史是「之前到什么程度」——混在一起会互相干扰；</li><li><strong>长任务分阶段保存状态</strong>：不要一次塞进所有历史，用「状态文件」记录进度，分阶段交给它；</li><li><strong>第 7 章任务卡的「上下文」字段，在这里系统化</strong>：清单化、文件化，而不是每次重打。</li></ol><h2 id="必要概念" tabindex="-1">必要概念 <a class="header-anchor" href="#必要概念" aria-label="Permalink to &quot;必要概念&quot;">​</a></h2><ul><li><strong>上下文窗口（Context Window）</strong>：模型单次能处理的输入总量（有上限）。白话解释：它一次能「摊在桌面上」的材料是有限的。</li><li><strong>上下文不足（Under-context）</strong>：关键信息缺失，Agent 只能靠猜 → 结果不可靠。</li><li><strong>上下文过载（Over-context）</strong>：塞了太多无关信息，淹没了关键点 → 答非所问、抓不住重点。</li><li><strong>上下文污染（Context pollution）</strong>：错误或过时信息混入 → 被带偏，且越信越错。</li><li><strong>状态文件（State file）</strong>：记录任务进度的文件（已完成/待办/决策/风险）。白话解释：任务的中途存档。</li></ul><h2 id="项目上下文清单" tabindex="-1">项目上下文清单 <a class="header-anchor" href="#项目上下文清单" aria-label="Permalink to &quot;项目上下文清单&quot;">​</a></h2><p>在任务卡基础上，为长期项目维护一份清单（放项目根目录，如 <code>CONTEXT.md</code>）：</p><table tabindex="0"><thead><tr><th>模块</th><th>内容</th><th>什么时候更新</th></tr></thead><tbody><tr><td>项目一句话</td><td>做什么、当前阶段</td><td>阶段切换时</td></tr><tr><td>关键事实</td><td>已确认的事实与来源（带日期）</td><td>事实变化时</td></tr><tr><td>决策记录</td><td>做过什么决定、为什么</td><td>每次决策后</td></tr><tr><td>状态</td><td>当前进度：已完成/进行中/待办</td><td>每次任务后</td></tr><tr><td>规则与约定</td><td>命名、口径、边界（引用第 14 章）</td><td>规则变更时</td></tr><tr><td>历史摘要</td><td>已完成任务的要点（不是全文）</td><td>每次任务后追加摘要</td></tr><tr><td>易变信息表</td><td>价格、福利、版本及核验日期</td><td>定期核验（<code>docs/07</code> 就是范例）</td></tr></tbody></table><h2 id="跟着做-建立并维护项目上下文" tabindex="-1">跟着做：建立并维护项目上下文 <a class="header-anchor" href="#跟着做-建立并维护项目上下文" aria-label="Permalink to &quot;跟着做：建立并维护项目上下文&quot;">​</a></h2><h3 id="第一步-建-context-md" tabindex="-1">第一步：建 <code>CONTEXT.md</code> <a class="header-anchor" href="#第一步-建-context-md" aria-label="Permalink to &quot;第一步：建 `CONTEXT.md`&quot;">​</a></h3><p>按上面清单建文件，先填「项目一句话 + 关键事实 + 状态」。</p><h3 id="第二步-任务开始时「喂上下文」" tabindex="-1">第二步：任务开始时「喂上下文」 <a class="header-anchor" href="#第二步-任务开始时「喂上下文」" aria-label="Permalink to &quot;第二步：任务开始时「喂上下文」&quot;">​</a></h3><p>每次发任务，在任务卡里写清楚：<strong>本次要用哪些材料（路径）、遵守哪些规则（引用 CONTEXT.md 相应节）、上次进度到哪（引用状态）</strong>。不要贴全文，贴「入口 + 摘要」。</p><h3 id="第三步-防污染三查" tabindex="-1">第三步：防污染三查 <a class="header-anchor" href="#第三步-防污染三查" aria-label="Permalink to &quot;第三步：防污染三查&quot;">​</a></h3><ul><li><strong>查过时</strong>：材料里有没有「测试前状态」？用之前核对日期；</li><li><strong>查冲突</strong>：新材料与已有事实冲突时，以哪个为准、记录在哪；</li><li><strong>查残留</strong>：对话里有没有上一次任务的残留指令？（新任务开新会话/新任务，别续旧对话）</li></ul><h3 id="第四步-长任务分段存档" tabindex="-1">第四步：长任务分段存档 <a class="header-anchor" href="#第四步-长任务分段存档" aria-label="Permalink to &quot;第四步：长任务分段存档&quot;">​</a></h3><blockquote><p>阶段 1 完成 → 写状态文件（产出清单 + 决策 + 遗留问题）→ 阶段 2 任务卡引用状态文件继续 → 依此类推。</p></blockquote><p>分段存档的好处：即使上下文窗口有限，每个阶段只带「摘要 + 本阶段材料」，既不过载也不丢。</p><h2 id="一个完整示例" tabindex="-1">一个完整示例 <a class="header-anchor" href="#一个完整示例" aria-label="Permalink to &quot;一个完整示例&quot;">​</a></h2><p>本书项目就是活例子：</p><ul><li>根目录维护 <code>docs/</code> 系列（项目简报、目录、编辑规范、内容清单）——每份文档只负责一个主题（第 5 篇网站化约定的实践）；</li><li><code>research/runs/*/run-record.md</code> 是每个实测任务的状态文件：计时、介入、问题、结论，一次任务一存档；</li><li><code>research/benchmark-summary-2026-08-12.md</code> 是七次任务的历史摘要——写第 5、6 章时不用重读七份记录，读摘要即可；</li><li><code>docs/07</code> 是易变信息表（价格核验日期），产品页引用它而不是把价格写死在正文。</li></ul><p><strong>结果</strong>：跨几十个文件的长期项目，任何一次写作任务只需引用「摘要 + 材料 + 规则」，上下文既不过载也不污染。</p><h2 id="常见错误与恢复方法" tabindex="-1">常见错误与恢复方法 <a class="header-anchor" href="#常见错误与恢复方法" aria-label="Permalink to &quot;常见错误与恢复方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>Agent 不知道刚做过的事</td><td>新会话没带状态</td><td>任务卡里引用状态文件摘要</td></tr><tr><td>回答里混入旧版本信息</td><td>上下文污染</td><td>核对材料日期，更新 CONTEXT.md</td></tr><tr><td>塞了 50 个文件它抓不住重点</td><td>上下文过载</td><td>只给本次相关材料 + 摘要</td></tr><tr><td>把「材料里没有」当成「事实不存在」</td><td>上下文不足</td><td>任务卡写明「输入范围外视为未提供，不要推断」</td></tr><tr><td>越聊越乱</td><td>残留指令污染</td><td>新任务开新会话/新任务</td></tr></tbody></table><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li>CONTEXT.md 里不要存密码、Token、身份证号等敏感信息——它会被 Agent 反复读取；</li><li>状态文件更新前确认信息仍有效，避免把过时状态再喂回去。</li></ul><h2 id="本章练习" tabindex="-1">本章练习 <a class="header-anchor" href="#本章练习" aria-label="Permalink to &quot;本章练习&quot;">​</a></h2><p>30 分钟：为你的长期项目（或序章任务所在目录）创建 <code>CONTEXT.md</code>，完成「项目一句话 + 关键事实 + 状态 + 易变信息表」四个模块，并在下一次任务中实际引用它。</p><h2 id="你应该带走的成果" tabindex="-1">你应该带走的成果 <a class="header-anchor" href="#你应该带走的成果" aria-label="Permalink to &quot;你应该带走的成果&quot;">​</a></h2><ul><li><strong>项目上下文清单（CONTEXT.md）</strong>：关键事实、决策记录、状态、规则、历史摘要、易变信息表。</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>上下文是 Agent 的全部视野，没放进去的等于不存在；</li><li>三类问题：不足、过载、污染，各有对策；</li><li>材料、规则、历史分开给，混用会互相干扰；</li><li>长任务用状态文件分段存档；</li><li>CONTEXT.md 是长期项目的第一件基础设施。</li></ol>',38)])])}const m=a(o,[["render",l]]);export{g as __pageData,m as default};
